public struct FfiConverterTypeDakKern: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = DakKern

    public static func lift(_ handle: UInt64) throws -> DakKern {
        return DakKern(unsafeFromHandle: handle)
    }

    public static func lower(_ value: DakKern) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DakKern {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: DakKern, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


