// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceDakUhr {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceDakUhr = UniffiVTableCallbackInterfaceDakUhr(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeDakUhr.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface DakUhr: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeDakUhr.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface DakUhr: handle missing in uniffiClone")
            }
        },
        jetzt: { (
