public 
enum DakFehler: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Fehler(code: UInt32, meldung: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension DakFehler: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDakFehler: FfiConverterRustBuffer {
    typealias SwiftType = DakFehler

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DakFehler {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Fehler(
            code: try FfiConverterUInt32.read(from: &buf), 
            meldung: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DakFehler, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Fehler(code,meldung):
            writeInt(&buf, Int32(1))
            FfiConverterUInt32.write(code, into: &buf)
            FfiConverterString.write(meldung, into: &buf)
            
        }
