        case 2: return .gesperrt(generation: try FfiConverterUInt64.read(from: &buf), generationH: try FfiConverterUInt64.read(from: &buf), kkUmhuellung: try FfiConverterOptionData.read(from: &buf), kkHUmhuellung: try FfiConverterOptionData.read(from: &buf)
